#!/usr/bin/env python3
"""As 8 aulas do Kit de Gestão para Advogados. Uso: python3 build_aulas.py [nome...]
Cenas: capa · tela (captura docs/tela-NN.png com foco [x,y,w,h] em frações) · card · lista · fim.
Nada jurídico: a planilha AVISA; o controle é do escritório. Prompts citados pelo nome real da planilha 21."""
import sys, video_engine as V
T=lambda img,foco,fala,leg: {'tipo':'tela','img':img,'foco':foco,'fala':fala,'legenda':leg}
